//! Clustering parity with base R's `hclust` on the matrices of
//! `tests/fixtures/hclust_reference.json` (generated by
//! `tests/fixtures/generate_hclust_reference.R`): same merges, same leaf order,
//! heights within rounding.

use ggrust_core::cluster::{Distance, Linkage, cluster_rows};
use serde_json::Value;

#[test]
fn clusterings_match_r_hclust() {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/fixtures/hclust_reference.json"
    );
    let text = std::fs::read_to_string(path).expect("reference fixture");
    let cases: Vec<Value> = serde_json::from_str(&text).expect("json");
    assert_eq!(cases.len(), 40);
    for case in &cases {
        let label = format!("{} {} {}", case["name"], case["method"], case["distance"]);
        let rows: Vec<Vec<f64>> = serde_json::from_value(case["matrix"].clone()).expect("matrix");
        let columns = rows[0].len();
        let values: Vec<f64> = rows.concat();
        let labels = (1..=rows.len()).map(|index| index.to_string()).collect();
        let distance = Distance::from_name(case["distance"].as_str().expect("name")).expect("d");
        let linkage = Linkage::from_name(case["method"].as_str().expect("name")).expect("m");
        let tree = cluster_rows(&values, columns, labels, distance, linkage).expect(&label);
        let merge: Vec<[i64; 2]> = serde_json::from_value(case["merge"].clone()).expect("merge");
        let height: Vec<f64> = serde_json::from_value(case["height"].clone()).expect("height");
        let order: Vec<usize> = serde_json::from_value(case["order"].clone()).expect("order");
        assert_eq!(tree.merge, merge, "{label}: merge");
        let order: Vec<usize> = order.into_iter().map(|leaf| leaf - 1).collect();
        assert_eq!(tree.order, order, "{label}: order");
        for (step, (ours, theirs)) in tree.height.iter().zip(&height).enumerate() {
            assert!(
                (ours - theirs).abs() <= 1e-9 * theirs.abs().max(1.0),
                "{label}: height {step}: {ours} vs {theirs}"
            );
        }
    }
}
